sys_relationship.query_with:
(function refineQuery(current, parent) {

    // 1. Filter by Organismo: Match the Iniciativa organism with the Plan's organism
    current.addQuery("company", parent.getValue("company"));

    // 2. Filter by Year: Match the year of 'fecha_licitacion' with the 'ano' field of the Plan
    var planYear = parent.getValue("ano");
    if (planYear) {
        // Construct an encoded query to filter 'fecha_licitacion' for the specific year
        var queryStr = "fecha_licitacionON" + planYear +
            "@javascript:gs.dateGenerate('" + planYear + "-01-01','start')" +
            "@javascript:gs.dateGenerate('" + planYear + "-12-31','end')";
        current.addEncodedQuery(queryStr);
    }
		current.addQuery("state","6");

})(current, parent);
